class Channel(AbstractChannel):
    """Bidirectional asynchronous channel.

    Built on top of two queues, this channel can be used in
    asynchronous producers and consumers.
    """

    def __init__(self, maxsize=0):
        from .queues import Queue
        self._queue = Queue(maxsize)
        self._closed = False

    async def send(self, item):
        """Send an item to the channel.

        This method blocks if the queue is full.
        """
        if self._closed:
            raise RuntimeError('Channel is closed.')
        await self._queue.put(item)

    async def recv(self):
        """Receive an item from the channel.

        This method blocks if the queue is empty.
        """
        if self._closed:
            raise RuntimeError('Channel is closed.')
        return await self._queue.get()

    def close(self):
        """Close the channel.

        This method unblocks any pending senders or receivers.
        """
        self._closed = True


